\label{tab:threshold_gap}
\begin{tabular}{@{}lccccr@{}}
\toprule
 & GDN & RetNet & HGRN2 & Range & Rel.\ spread \\
\midrule
Rescue & 3.32 & 3.29 & 3.31 & 0.03 & 1.0\% \\
Disruption & 0.70 & 1.00 & 1.14 & 0.44 & 46.7\% \\
